links=[('최신 실행 파일','EngineMigrator-runtime-destroy-preview-20261023/EngineMigrator.App.exe'),('배포 ZIP','EngineMigrator-runtime-destroy-preview-20261023.zip'),('사용 가이드','../docs/guide.html'),('실행 검증 근거','runtime-destroy-tests/milestone-verification.json'),('프로젝트 왕복 대조','runtime-destroy-roundtrip-v3/PROJECT-e22275670ee5/project-roundtrip-verification.json'),('실제 변환 대응표','runtime-destroy-roundtrip-v3/PROJECT-e22275670ee5/resource-port.html'),('수정 전 실행 차이','runtime-destroy-tests/unreal-v1-observed.json'),('이전 단계 보고서','development-report-runtime-order-20261023.html')]
